-- RAG 지식베이스 (docs/agent-spec.md RAG 절)
-- pgvector 확장이 필요하다. docker-compose는 pgvector 이미지를 사용한다.
CREATE EXTENSION IF NOT EXISTS vector;

-- 지식 문서 (원문 단위)
CREATE TABLE IF NOT EXISTS "knowledge_documents" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 출처 구분: TERMS 약관 / PRODUCT 상품설명 / FAQ 앱 사용·정책 / GUIDE 소비관리 가이드
	"source_type" VARCHAR(20) NOT NULL,
	"title" VARCHAR(200) NOT NULL,
	-- 원본 위치 (파일 경로 또는 테이블명:ID)
	"source_ref" VARCHAR(300) NOT NULL UNIQUE,
	"version" VARCHAR(20),
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "knowledge_documents" IS 'RAG 지식 문서';
COMMENT ON COLUMN "knowledge_documents"."source_type" IS '출처 구분: TERMS 약관 / PRODUCT 상품설명 / FAQ 앱 사용·정책 / GUIDE 소비관리 가이드';

-- 지식 조각 (검색 단위). 회원 개인 거래 데이터는 넣지 않는다.
CREATE TABLE IF NOT EXISTS "knowledge_chunks" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"document_id" BIGINT NOT NULL,
	-- 문서 내 순서
	"chunk_index" INT NOT NULL,
	"content" TEXT NOT NULL,
	-- 임베딩 벡터. 차원은 사용할 Gemini 임베딩 설정에 맞춰 확정(초안 768)
	"embedding" vector(768) NOT NULL,
	PRIMARY KEY("id"),
	UNIQUE ("document_id", "chunk_index")
);

CREATE INDEX "idx_knowledge_chunks_embedding"
ON "knowledge_chunks" USING hnsw ("embedding" vector_cosine_ops);

COMMENT ON TABLE "knowledge_chunks" IS 'RAG 지식 조각과 임베딩';

ALTER TABLE "knowledge_chunks"
ADD FOREIGN KEY("document_id") REFERENCES "knowledge_documents"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
